CREATE OR REPLACE FUNCTION public.acknowledge_spec_discrepancy(p_project uuid, p_mark text, p_kind text, p_note text DEFAULT NULL::text, p_issue_note text DEFAULT NULL::text)
 RETURNS project_spec_discrepancies
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_row project_spec_discrepancies;
  v_issue issues;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can label a spec discrepancy';
  end if;

  insert into project_spec_discrepancies (
    project_id, mark_code, kind, note, status, acknowledged_by, acknowledged_at
  )
  values (
    p_project, p_mark, p_kind, nullif(trim(coalesce(p_note, '')), ''),
    'acknowledged', auth.uid(), now()
  )
  on conflict (project_id, mark_code, kind) do update
    set note = nullif(trim(coalesce(p_note, '')), ''),
        status = 'acknowledged',
        acknowledged_by = auth.uid(),
        acknowledged_at = now()
  returning * into v_row;

  if v_row.issue_id is null then
    insert into issues (
      project_id, opening_id, kind, urgency, note, created_by, assigned_to
    )
    values (
      p_project, null, 'spec_gap', 'normal',
      coalesce(p_issue_note, p_note), auth.uid(), auth.uid()
    )
    returning * into v_issue;

    update project_spec_discrepancies
    set issue_id = v_issue.id
    where id = v_row.id
    returning * into v_row;
  else
    update issues
    set status = 'open', resolved_by = null, resolved_at = null
    where id = v_row.issue_id and status = 'resolved';
  end if;

  return v_row;
end;
$function$

CREATE OR REPLACE FUNCTION public.activate_preissued_unit(p_code text, p_location_id uuid DEFAULT NULL::uuid, p_damaged boolean DEFAULT false, p_actor text DEFAULT NULL::text)
 RETURNS windows
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_role text;
  v_unit windows;
  v_new_status text;
begin
  select role into v_caller_role from profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can receive against the plan';
  end if;

  select * into v_unit from find_window_by_code(p_code);
  if v_unit.id is null then
    raise exception 'unknown code % — no unit matches that code or serial', p_code;
  end if;
  if v_unit.status <> 'pre_issued' then
    raise exception
      'window % is not awaiting delivery (status %) — it may already be received',
      v_unit.window_id, v_unit.status;
  end if;

  v_new_status := case when p_damaged then 'damaged' else 'in_warehouse' end;

  update windows
  set status = v_new_status,
      location_id = coalesce(p_location_id, location_id),
      received_at = now()
  where id = v_unit.id
  returning * into v_unit;

  insert into movements (window_id, event, to_location_id, project_id, actor, reason)
  values (
    v_unit.id,
    'received',
    p_location_id,
    v_unit.project_id,
    coalesce(p_actor, auth.uid()::text),
    case when p_damaged then 'received damaged on arrival' else null end
  );

  if p_damaged then
    if not exists (
      select 1 from issues
      where kind = 'damage' and status = 'open'
        and (
          window_id = v_unit.id
          or opening_id = (
            select id from project_openings
            where assigned_window_id = v_unit.id
            limit 1
          )
        )
    ) then
      insert into issues (project_id, opening_id, window_id, kind, urgency, note, created_by)
      values (v_unit.project_id, null, v_unit.id, 'damage', 'urgent',
              'damaged on arrival', auth.uid());
    end if;
  else
    update issues
    set status = 'resolved', resolved_at = now(), resolved_by = auth.uid()
    where window_id = v_unit.id and kind = 'missing' and status = 'open';
  end if;

  return v_unit;
end;
$function$

CREATE OR REPLACE FUNCTION public.add_job_note(p_project_id uuid, p_note text)
 RETURNS job_notes
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_note job_notes; v_name text;
begin
  select display_name into v_name from profiles where id = auth.uid();
  insert into job_notes (project_id, author_id, author_name, note)
  values (p_project_id, auth.uid(), v_name, p_note)
  returning * into v_note;
  return v_note;
end;
$function$

CREATE OR REPLACE FUNCTION public.ai_spend_reserve(p_user_id uuid, p_function text, p_kind text DEFAULT 'question'::text, p_estimate_micros bigint DEFAULT 0, p_provider text DEFAULT NULL::text, p_model text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_cfg ai_spend_limits;
  v_day date;
  v_month date;
  v_kind text := case when p_kind = 'content' then 'content' else 'question' end;
  v_estimate bigint := greatest(0, coalesce(p_estimate_micros, 0));
  v_rank integer;
  v_min_rank integer;
  v_calls integer;
  v_cap_micros bigint;
  v_effective_cap bigint;
  v_reserved bigint;
  v_event_id uuid;
  v_alert text := null;
  v_counted boolean := false;

  -- Who to tell when a threshold is crossed. Resolved here rather than in the
  -- edge function because this is already SECURITY DEFINER and can read
  -- profiles without depending on their RLS policies (which are being reworked
  -- separately) — and it saves the guard a round trip on the one call that has
  -- just been told there is a problem.
  v_owner_ids jsonb := '[]'::jsonb;
begin
  select * into v_cfg from ai_spend_limits where id = 1;
  if not found then
    insert into ai_spend_limits (id) values (1)
      on conflict (id) do nothing;
    select * into v_cfg from ai_spend_limits where id = 1;
  end if;

  v_day := (now() at time zone v_cfg.timezone)::date;
  v_month := date_trunc('month', (now() at time zone v_cfg.timezone))::date;

  v_min_rank := case v_cfg.min_role
    when 'owner' then 3
    when 'supervisor' then 2
    when 'foreman' then 1
    else 0
  end;

  v_cap_micros := v_cfg.monthly_cap_cents::bigint * 10000;
  v_effective_cap := case
    when v_kind = 'content'
      then (v_cap_micros * v_cfg.content_multiplier)::bigint
    else v_cap_micros
  end;

  -- (1) Role floor. Only applies to `question` traffic and only to a real end
  -- user: `content` jobs and service-role/webhook callers (null user) carry no
  -- role and are gated by the ceiling alone.
  if v_cfg.enforced and v_kind = 'question' and p_user_id is not null then
    v_rank := ai_role_rank(p_user_id);
    if v_rank < v_min_rank then
      insert into ai_usage_events (
        user_id, function_name, kind, provider, model, outcome,
        estimate_micros, usage_day, usage_month
      ) values (
        p_user_id, p_function, v_kind, p_provider, p_model, 'denied_role',
        0, v_day, v_month
      ) returning id into v_event_id;
      return jsonb_build_object(
        'allowed', false,
        'reason', 'role',
        'reservation_id', v_event_id,
        'min_role', v_cfg.min_role
      );
    end if;
  end if;

  -- (2) Per-user daily count. ONE statement: the upsert locks the day row, so a
  -- burst of concurrent callers queues on it and each one tests the limit
  -- against the value the previous caller actually committed. When the guard
  -- fails no row comes back, which IS the refusal — there is no window between
  -- reading the count and writing it.
  if v_cfg.enforced and v_kind = 'question' and p_user_id is not null then
    insert into ai_usage_days (user_id, usage_day, calls)
    values (p_user_id, v_day, 1)
    on conflict (user_id, usage_day) do update
      set calls = ai_usage_days.calls + 1,
          updated_at = now()
      where ai_usage_days.calls < v_cfg.per_user_daily_calls
    returning calls into v_calls;

    if v_calls is null then
      insert into ai_usage_events (
        user_id, function_name, kind, provider, model, outcome,
        estimate_micros, usage_day, usage_month
      ) values (
        p_user_id, p_function, v_kind, p_provider, p_model, 'denied_user_daily',
        0, v_day, v_month
      ) returning id into v_event_id;
      return jsonb_build_object(
        'allowed', false,
        'reason', 'user_daily',
        'reservation_id', v_event_id,
        'daily_limit', v_cfg.per_user_daily_calls
      );
    end if;
    v_counted := true;
  elsif p_user_id is not null then
    -- Not gated, but still metered, so the owner screen shows every caller.
    insert into ai_usage_days (user_id, usage_day, calls)
    values (p_user_id, v_day, 1)
    on conflict (user_id, usage_day) do update
      set calls = ai_usage_days.calls + 1, updated_at = now()
    returning calls into v_calls;
    v_counted := true;
  end if;

  -- (3) Company monthly ceiling, tested against money already booked. Same
  -- single-statement pattern, so the ceiling holds under a burst too.
  if v_cfg.enforced then
    insert into ai_spend_months (usage_month, calls, reserved_micros)
    values (v_month, 1, v_estimate)
    on conflict (usage_month) do update
      set calls = ai_spend_months.calls + 1,
          reserved_micros = ai_spend_months.reserved_micros + v_estimate,
          updated_at = now()
      where ai_spend_months.reserved_micros < v_effective_cap
    returning reserved_micros into v_reserved;
  else
    insert into ai_spend_months (usage_month, calls, reserved_micros)
    values (v_month, 1, v_estimate)
    on conflict (usage_month) do update
      set calls = ai_spend_months.calls + 1,
          reserved_micros = ai_spend_months.reserved_micros + v_estimate,
          updated_at = now()
    returning reserved_micros into v_reserved;
  end if;

  if v_reserved is null then
    -- Ceiling refused. Give the user back the day-count we just took: their
    -- own quota should not be burned by the company running out of budget.
    if v_counted then
      update ai_usage_days
         set calls = greatest(0, calls - 1), updated_at = now()
       where user_id = p_user_id and usage_day = v_day;
    end if;

    insert into ai_usage_events (
      user_id, function_name, kind, provider, model, outcome,
      estimate_micros, usage_day, usage_month
    ) values (
      p_user_id, p_function, v_kind, p_provider, p_model, 'denied_monthly_cap',
      0, v_day, v_month
    ) returning id into v_event_id;

    insert into ai_spend_alerts (usage_month, level, reserved_micros, cap_micros)
    select v_month, 'cap',
           coalesce((select reserved_micros from ai_spend_months where usage_month = v_month), 0),
           v_cap_micros
    on conflict (usage_month, level) do nothing
    returning level into v_alert;

    if v_alert is not null then
      select coalesce(jsonb_agg(id), '[]'::jsonb) into v_owner_ids
        from profiles where role in ('owner', 'big_boss', 'supervisor', 'admin');
    end if;

    return jsonb_build_object(
      'allowed', false,
      'reason', 'monthly_cap',
      'reservation_id', v_event_id,
      'cap_micros', v_cap_micros,
      'alert', v_alert,
      'alert_profile_ids', v_owner_ids
    );
  end if;

  -- (4) Approaching the ceiling: raise the warn alert exactly once.
  if v_cap_micros > 0
     and v_reserved >= (v_cap_micros * v_cfg.alert_at_pct) / 100 then
    insert into ai_spend_alerts (usage_month, level, reserved_micros, cap_micros)
    values (v_month, 'warn', v_reserved, v_cap_micros)
    on conflict (usage_month, level) do nothing
    returning level into v_alert;

    if v_alert is not null then
      select coalesce(jsonb_agg(id), '[]'::jsonb) into v_owner_ids
        from profiles where role in ('owner', 'big_boss', 'supervisor', 'admin');
    end if;
  end if;

  insert into ai_usage_events (
    user_id, function_name, kind, provider, model, outcome,
    estimate_micros, usage_day, usage_month
  ) values (
    p_user_id, p_function, v_kind, p_provider, p_model, 'allowed',
    v_estimate, v_day, v_month
  ) returning id into v_event_id;

  return jsonb_build_object(
    'allowed', true,
    'reason', null,
    'reservation_id', v_event_id,
    'calls_today', v_calls,
    'daily_limit', v_cfg.per_user_daily_calls,
    'reserved_micros', v_reserved,
    'cap_micros', v_cap_micros,
    'alert', v_alert,
    'alert_profile_ids', v_owner_ids
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.approve_shift(p_shift_id uuid)
 RETURNS time_shifts
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text; v_shift time_shifts;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a lead-level user can approve';
  end if;
  update time_shifts set status='approved', approved_by=auth.uid(), approved_at=now()
  where id = p_shift_id returning * into v_shift;
  return v_shift;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_issue(p_id uuid, p_assignee uuid DEFAULT NULL::uuid)
 RETURNS issues
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_issue issues;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role = 'installer' then
    raise exception 'only a foreman-level user or above can assign an issue';
  end if;

  update issues
  set assigned_to = p_assignee
  where id = p_id
  returning * into v_issue;
  if v_issue is null then
    raise exception 'unknown issue %', p_id;
  end if;
  return v_issue;
end;
$function$

CREATE OR REPLACE FUNCTION public.assign_window_to_opening(p_opening_id uuid, p_window_id uuid, p_actor text DEFAULT NULL::text)
 RETURNS project_openings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opening project_openings;
  v_window windows;
begin
  select * into v_opening from project_openings where id = p_opening_id;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;
  if v_opening.status = 'installed' then
    raise exception 'opening % is already installed', v_opening.opening_code;
  end if;

  select * into v_window from windows where id = p_window_id;
  if v_window is null then
    raise exception 'unknown window %', p_window_id;
  end if;
  if v_window.status = 'installed' then
    raise exception '% is already installed', v_window.window_id;
  end if;
  if v_opening.window_type_id is not null
     and v_window.window_type_id <> v_opening.window_type_id then
    raise exception 'type mismatch: % is not the type planned for opening %',
      v_window.window_id, v_opening.opening_code;
  end if;

  update windows
  set project_id = v_opening.project_id
  where id = v_window.id
    and (project_id is distinct from v_opening.project_id);

  update project_openings
  set assigned_window_id = v_window.id,
      window_type_id = coalesce(window_type_id, v_window.window_type_id),
      status = 'assigned'
  where id = p_opening_id
  returning * into v_opening;

  insert into movements (window_id, event, project_id, actor, reason)
  values (
    v_window.id,
    'assigned',
    v_opening.project_id,
    p_actor,
    'assigned to opening ' || v_opening.opening_code
  );

  return v_opening;
end;
$function$

CREATE OR REPLACE FUNCTION public.check_my_pin(p_pin text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_hash text;
begin
  select pin_hash into v_hash from public.profiles where id = auth.uid();
  if v_hash is null or coalesce(p_pin, '') = '' then
    return false;
  end if;
  -- Re-derives with the salt and cost embedded in the stored hash. The compared
  -- values are hashes, so a byte-wise comparison leaks nothing about the PIN.
  return extensions.crypt(p_pin, v_hash) = v_hash;
end;
$function$

CREATE OR REPLACE FUNCTION public.claim_owner_bootstrap()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
begin
  if auth.uid() is null then
    return false;
  end if;

  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if v_email not in ('ammon@horizonsolarusa.com', 'isaacammonbarlow@gmail.com') then
    return false;
  end if;

  update public.profiles
     set role = 'owner',
         display_name = 'Ammon',
         active = true,
         updated_at = now()
   where id = auth.uid()
     and (role <> 'owner' or display_name <> 'Ammon' or not active);

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.clock_in(p_project_id uuid, p_cost_code_id uuid, p_photo text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision)
 RETURNS time_shifts
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v_shift time_shifts;
begin
  -- Hard gate: today's toolbox talk must be signed before clocking in.
  if not exists (
    select 1 from toolbox_completions
    where profile_id = auth.uid() and signed_at::date = current_date
  ) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  -- Close any dangling open shift for this user first (also powers job/phase
  -- switching: clocking in elsewhere submits the prior shift with no gap).
  update time_shifts set clock_out_at = now(), status = 'submitted'
  where profile_id = auth.uid() and status = 'open' and clock_out_at is null;

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng)
  values (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng)
  returning * into v_shift;
  return v_shift;
end;
$function$

CREATE OR REPLACE FUNCTION public.clock_in(p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision, p_client_id uuid)
 RETURNS time_shifts
 LANGUAGE plpgsql
AS $function$
declare v_shift time_shifts;
begin
  if p_client_id is not null then
    select * into v_shift from time_shifts
      where client_id = p_client_id and profile_id = auth.uid();
    if v_shift.id is not null then
      return v_shift;
    end if;
  end if;

  if not exists (
    select 1 from toolbox_completions
    where profile_id = auth.uid() and signed_at::date = current_date
  ) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  update time_shifts set clock_out_at = now(), status = 'submitted'
  where profile_id = auth.uid() and status = 'open' and clock_out_at is null;

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng, client_id)
  values
    (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng, p_client_id)
  returning * into v_shift;
  return v_shift;
end;
$function$

CREATE OR REPLACE FUNCTION public.clock_in(p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision, p_client_id uuid, p_note text)
 RETURNS time_shifts
 LANGUAGE plpgsql
AS $function$
declare v_shift time_shifts;
begin
  if p_client_id is not null then
    select * into v_shift from time_shifts
      where client_id = p_client_id and profile_id = auth.uid();
    if v_shift.id is not null then
      return v_shift;
    end if;
  end if;

  if not exists (
    select 1 from toolbox_completions
    where profile_id = auth.uid() and signed_at::date = current_date
  ) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  update time_shifts set clock_out_at = now(), status = 'submitted'
  where profile_id = auth.uid() and status = 'open' and clock_out_at is null;

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng,
     client_id, note)
  values
    (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng,
     p_client_id, nullif(btrim(p_note), ''))
  returning * into v_shift;
  return v_shift;
end;
$function$

CREATE OR REPLACE FUNCTION public.clock_in(p_project_id uuid, p_cost_code_id uuid, p_photo text, p_lat double precision, p_lng double precision, p_note text)
 RETURNS time_shifts
 LANGUAGE plpgsql
AS $function$
declare v_shift time_shifts;
begin
  if not exists (
    select 1 from toolbox_completions
    where profile_id = auth.uid() and signed_at::date = current_date
  ) then
    raise exception 'complete today''s toolbox talk before clocking in';
  end if;

  update time_shifts set clock_out_at = now(), status = 'submitted'
  where profile_id = auth.uid() and status = 'open' and clock_out_at is null;

  insert into time_shifts
    (profile_id, project_id, cost_code_id, clock_in_photo, clock_in_lat, clock_in_lng, note)
  values
    (auth.uid(), p_project_id, p_cost_code_id, p_photo, p_lat, p_lng,
     nullif(btrim(p_note), ''))
  returning * into v_shift;
  return v_shift;
end;
$function$

CREATE OR REPLACE FUNCTION public.end_break(p_shift_id uuid)
 RETURNS time_shifts
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v time_shifts;
begin
  update time_shifts
  set break_seconds = break_seconds
        + greatest(0, extract(epoch from (now() - break_started_at))::int),
      break_started_at = null,
      break_type = null
  where id = p_shift_id and profile_id = auth.uid() and break_started_at is not null
  returning * into v;
  if v is null then
    select * into v from time_shifts where id = p_shift_id and profile_id = auth.uid();
  end if;
  return v;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_project_staging_bays(p_project_id uuid)
 RETURNS SETOF locations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_caller_role text;
  v_job_code text;
begin
  select role into v_caller_role from public.profiles where id = auth.uid();
  if v_caller_role is null or v_caller_role = 'installer' then
    raise exception 'only a foreman-level user or above can create staging bays';
  end if;

  select job_code into v_job_code from public.projects where id = p_project_id;
  if v_job_code is null then
    raise exception 'unknown job %', p_project_id;
  end if;

  return query select * from public.create_staging_bays(v_job_code);
end;
$function$

CREATE OR REPLACE FUNCTION public.flag_opening(p_opening_id uuid, p_note text)
 RETURNS project_openings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opening project_openings;
  v_clean text;
begin
  v_clean := nullif(trim(coalesce(p_note, '')), '');

  update project_openings
  set flag_note = v_clean,
      flagged_by = case when v_clean is null then null else auth.uid() end,
      flagged_at = case when v_clean is null then null else now() end
  where id = p_opening_id
  returning * into v_opening;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  if v_clean is null then
    -- Flag cleared: resolve any open flag issues for this opening.
    update issues
    set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
    where opening_id = p_opening_id and kind = 'flag' and status = 'open';
  else
    -- Flag set: open a flag issue unless one is already open.
    if not exists (
      select 1 from issues
      where opening_id = p_opening_id and kind = 'flag' and status = 'open'
    ) then
      insert into issues (project_id, opening_id, kind, urgency, note, created_by)
      values (v_opening.project_id, p_opening_id, 'flag', 'normal', v_clean, auth.uid());
    end if;
  end if;

  return v_opening;
end;
$function$

CREATE OR REPLACE FUNCTION public.gen_short_code(p_len integer DEFAULT 6)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_alphabet text := 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  v_out text := '';
  i int;
begin
  for i in 1..p_len loop
    v_out := v_out || substr(v_alphabet, 1 + floor(random() * length(v_alphabet))::int, 1);
  end loop;
  return v_out;
end;
$function$

CREATE OR REPLACE FUNCTION public.issue_window_id(p_type_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_code text;
  v_seq int;
begin
  select type_code into v_code from window_types where id = p_type_id;
  if v_code is null then
    raise exception 'unknown window type %', p_type_id;
  end if;

  insert into window_id_counters (window_type_id, last_seq)
  values (p_type_id, 1)
  on conflict (window_type_id)
  do update set last_seq = window_id_counters.last_seq + 1
  returning last_seq into v_seq;

  return 'W-' || v_code || '-' || lpad(v_seq::text, 4, '0');
end;
$function$

