CREATE OR REPLACE FUNCTION public.set_my_pin(p_pin text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v text := coalesce(trim(p_pin), '');
begin
  if auth.uid() is null then
    raise exception 'sign in before setting a PIN' using errcode = '42501';
  end if;

  -- Empty means "clear my PIN", which the Roster screen offers explicitly.
  if v = '' then
    update public.profiles
       set pin_hash = null, updated_at = now()
     where id = auth.uid();
    return;
  end if;

  -- Mirrors validateNewPin() in supabase/functions/_shared/pin.ts.
  if length(v) < 4 or length(v) > 10 or v !~ '^[A-Za-z0-9]+$' then
    raise exception 'PIN must be 4-10 letters or numbers' using errcode = '22023';
  end if;

  update public.profiles
     set pin_hash = extensions.crypt(v, extensions.gen_salt('bf', 10)),
         updated_at = now()
   where id = auth.uid();
end;
$function$

CREATE OR REPLACE FUNCTION public.set_opening_condition(p_opening_id uuid, p_condition text, p_note text DEFAULT NULL::text, p_actor text DEFAULT NULL::text)
 RETURNS project_openings
 LANGUAGE plpgsql
AS $function$
declare
  v_opening project_openings;
begin
  if p_condition not in ('unknown','ok','damaged') then
    raise exception 'invalid condition %', p_condition;
  end if;

  update project_openings
  set condition = p_condition,
      condition_note = p_note,
      condition_checked_by = p_actor,
      condition_checked_at = now()
  where id = p_opening_id
  returning * into v_opening;

  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  if p_condition = 'damaged' and v_opening.assigned_window_id is not null then
    update windows set status = 'damaged' where id = v_opening.assigned_window_id;
    insert into movements (window_id, event, project_id, actor, reason)
    values (
      v_opening.assigned_window_id, 'damaged', v_opening.project_id, p_actor,
      coalesce('damaged at opening ' || v_opening.opening_code ||
        case when p_note is not null then ': ' || p_note else '' end,
        'damaged at opening')
    );
  end if;

  if p_condition = 'damaged' then
    if not exists (
      select 1 from issues
      where kind = 'damage' and status = 'open'
        and (
          opening_id = p_opening_id
          or window_id = v_opening.assigned_window_id
        )
    ) then
      insert into issues (project_id, opening_id, kind, urgency, note, created_by)
      values (v_opening.project_id, p_opening_id, 'damage', 'urgent', p_note, auth.uid());
    end if;
  else
    update issues
    set status = 'resolved', resolved_by = auth.uid(), resolved_at = now()
    where opening_id = p_opening_id and kind = 'damage' and status = 'open';
  end if;

  return v_opening;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_openings_sequence(p_opening_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  update project_openings o
  set sequence = arr.ord
  from (
    select id, (idx - 1) as ord
    from unnest(p_opening_ids) with ordinality as t(id, idx)
  ) arr
  where o.id = arr.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.set_profile_role(p_target uuid, p_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_rank int := public.my_role_rank();
  v_row  public.profiles;
begin
  if p_role not in ('installer', 'foreman', 'supervisor', 'owner') then
    raise exception 'invalid role %', p_role using errcode = '22023';
  end if;

  if v_rank < 2 then
    raise exception 'only a supervisor or owner can change roles'
      using errcode = '42501';
  end if;

  -- No self-promotion above your own rank: a supervisor cannot make themselves
  -- the owner. Lateral and downward self-changes stay allowed.
  if p_target = auth.uid() and public.role_rank(p_role) > v_rank then
    raise exception 'you cannot promote yourself above your own role'
      using errcode = '42501';
  end if;

  update public.profiles
     set role = p_role, updated_at = now()
   where id = p_target
  returning * into v_row;

  if v_row.id is null then
    raise exception 'no such profile %', p_target using errcode = 'P0002';
  end if;

  return jsonb_build_object(
    'id', v_row.id,
    'display_name', v_row.display_name,
    'role', v_row.role,
    'skill_level', v_row.skill_level,
    'active', v_row.active,
    'updated_at', v_row.updated_at
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.set_project_green_light(p_project uuid, p_on boolean, p_note text DEFAULT NULL::text)
 RETURNS projects
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_project projects;
begin
  select role into v_role from profiles where id = auth.uid();
  if v_role is null or v_role in ('installer', 'foreman', 'lead') then
    raise exception 'only a supervisor or above can set a project green light';
  end if;

  update projects
  set green_light = p_on,
      green_light_note = p_note,
      green_light_by = auth.uid(),
      green_light_at = now()
  where id = p_project
  returning * into v_project;

  if v_project is null then
    raise exception 'unknown project %', p_project;
  end if;

  return v_project;
end;
$function$

