CREATE OR REPLACE FUNCTION public.start_break(p_shift_id uuid, p_break_type text DEFAULT 'other'::text)
 RETURNS time_shifts
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare v time_shifts;
begin
  update time_shifts
  set break_started_at = coalesce(break_started_at, now()),
      break_type = coalesce(break_type, p_break_type)
  where id = p_shift_id and profile_id = auth.uid()
