CREATE OR REPLACE FUNCTION public.start_off_task(p_project uuid DEFAULT NULL::uuid)
 RETURNS task_sessions
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_session task_sessions;
  v_uid uuid := auth.uid();
begin
  perform close_open_task_sessions(v_uid);
  insert into task_sessions (profile_id, opening_id, project_id, state)
  values (v_uid, null, p_project, 'off_task')
  returning * into v_session;
  return v_session;
end;
$function$

CREATE OR REPLACE FUNCTION public.start_opening_work(p_opening_id uuid)
 RETURNS project_openings
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opening project_openings;
  v_uid uuid := auth.uid();
begin
  -- Gate: reconcile shift-time and task-time. You cannot be "on a task" unless
  -- you're clocked in and have signed today's toolbox talk.
  if not exists (
    select 1 from time_shifts
    where profile_id = v_uid and status = 'open' and clock_out_at is null
  ) then
    raise exception 'clock in and complete today''s toolbox talk before starting a task';
  end if;
  if not exists (
    select 1 from toolbox_completions
    where profile_id = v_uid and signed_at::date = current_date
  ) then
    raise exception 'clock in and complete today''s toolbox talk before starting a task';
  end if;

  update project_openings
  set work_started_at = coalesce(work_started_at, now())
  where id = p_opening_id
  returning * into v_opening;

  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  -- Reconcile task-time: close whatever the person was doing and land on_task.
  perform close_open_task_sessions(v_uid);
  insert into task_sessions (profile_id, opening_id, project_id, state)
  values (v_uid, v_opening.id, v_opening.project_id, 'on_task');

  return v_opening;
end;
$function$

CREATE OR REPLACE FUNCTION public.submit_install_event(p_opening_id uuid, p_installer text DEFAULT NULL::text, p_minutes integer DEFAULT NULL::integer, p_quality_grade integer DEFAULT NULL::integer, p_difficulty text DEFAULT NULL::text, p_went_well text DEFAULT NULL::text, p_went_poorly text DEFAULT NULL::text, p_obstacles text DEFAULT NULL::text, p_tools_helped text DEFAULT NULL::text, p_time_vs_estimate text DEFAULT NULL::text, p_safety_notes text DEFAULT NULL::text, p_do_again text DEFAULT NULL::text, p_transcript_raw text DEFAULT NULL::text, p_started_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_installer_id uuid DEFAULT NULL::uuid, p_estimate_minutes integer DEFAULT NULL::integer)
 RETURNS install_events
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_opening project_openings;
  v_event install_events;
  v_profile uuid := coalesce(p_installer_id, auth.uid());
begin
  select * into v_opening from project_openings where id = p_opening_id;
  if v_opening is null then
    raise exception 'unknown opening %', p_opening_id;
  end if;

  insert into install_events (
    project_opening_id, window_id, window_type_id, installer, installer_id,
    started_at, minutes, estimate_minutes, quality_grade, difficulty, went_well,
    went_poorly, obstacles, tools_helped, time_vs_estimate, safety_notes,
    do_again, transcript_raw
  ) values (
    v_opening.id, v_opening.assigned_window_id, v_opening.window_type_id,
    p_installer, v_profile, p_started_at, p_minutes,
    p_estimate_minutes, p_quality_grade, p_difficulty, p_went_well, p_went_poorly,
    p_obstacles, p_tools_helped, p_time_vs_estimate, p_safety_notes, p_do_again,
    p_transcript_raw
  )
  returning * into v_event;

  update project_openings
  set status = 'installed', confirmed = true, work_ended_at = now()
  where id = v_opening.id;

  if v_opening.assigned_window_id is not null then
    perform install_window(v_opening.assigned_window_id, p_installer);
  end if;

  -- Task-time: this window is done — close on_task, land off_task (between
  -- windows) until they tap "Next one" (which opens the next on_task session).
  if v_profile is not null then
    perform close_open_task_sessions(v_profile);
    insert into task_sessions (profile_id, opening_id, project_id, state)
    values (v_profile, null, v_opening.project_id, 'off_task');
  end if;

  return v_event;
end;
$function$

CREATE OR REPLACE FUNCTION public.suggest_location(p_window_id uuid)
 RETURNS locations
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
declare
  v_window windows;
  v_job_code text;
  v_bays int;
  v_loc locations;
begin
  select * into v_window from windows where id = p_window_id;
  if v_window is null then
    raise exception 'unknown window %', p_window_id;
  end if;

  if v_window.project_id is not null then
    select job_code into v_job_code from projects where id = v_window.project_id;

    select count(*) into v_bays
      from locations l
     where l.zone = 'J' and l.active and l.rack = v_job_code;

    if v_bays = 0 then
      raise exception
        'Job % has no staging bay, so there is no shelf of its own to put this window on. Create the job''s staging bays first — putting it on a shared stock shelf would mix this job''s windows in with everyone else''s.',
        coalesce(v_job_code, '(unknown)')
        using hint = 'no_staging_bay',
              detail = coalesce(v_job_code, '');
    end if;

    select l.* into v_loc
    from locations l
    join projects p on p.job_code = l.rack
    where l.zone = 'J' and l.active and p.id = v_window.project_id
      and (select count(*) from windows w where w.location_id = l.id) < l.capacity
    order by l.slot
    limit 1;
    if v_loc.id is not null then
      return v_loc;
    end if;
  end if;

  select l.* into v_loc
  from locations l
  where l.zone = 'S' and l.active
    and (select count(*) from windows w where w.location_id = l.id) < l.capacity
  order by
    (select count(*) from windows w
     where w.location_id = l.id and w.window_type_id = v_window.window_type_id) desc,
    (select count(*) from windows w where w.location_id = l.id) asc,
    l.address
  limit 1;

  return v_loc;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_guard_profile_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
begin
  if auth.uid() is null then
    return new;
  end if;

  if new.id <> auth.uid() then
    if public.my_role_rank() < 2 then
      raise exception 'you may only create your own profile'
        using errcode = '42501';
    end if;
    return new;
  end if;

  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if new.role is distinct from 'installer'
     and v_email not in ('ammon@horizonsolarusa.com', 'isaacammonbarlow@gmail.com')
  then
    raise exception
      'a new profile starts as installer; a supervisor or owner assigns the role'
      using errcode = '42501';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.trg_guard_profile_role_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_email text;
begin
  -- Service role / no JWT: migrations, seeds, edge functions on the service
  -- key. RLS and the grants above already keep anon out.
  if auth.uid() is null then
    return new;
  end if;

  -- Supervisor or owner: the sanctioned path (set_profile_role).
  if public.my_role_rank() >= 2 then
    return new;
  end if;

  -- Founder bootstrap, narrowed. The previous version let either founder email
  -- make ANY role change to ANY row; this allows exactly one thing — that
  -- account promoting itself to owner on first sign-in, which is how the very
  -- first owner comes to exist. Reachable only via claim_owner_bootstrap().
  v_email := lower(coalesce(auth.jwt() ->> 'email', ''));
  if new.id = auth.uid()
     and new.role = 'owner'
     and v_email in ('ammon@horizonsolarusa.com', 'isaacammonbarlow@gmail.com')
  then
    return new;
  end if;

  raise exception
    'only a supervisor or owner can change a role (blocked: % -> % on %)',
    old.role, new.role, old.id
    using errcode = '42501';
end;
$function$

